const r = $input.first().json;

let text = '';
try {
  text = r.candidates[0].content.parts.map(p => p.text).join('');
} catch (e) {
  const reason = (r.promptFeedback && r.promptFeedback.blockReason) || 'unknown';
  text = '## ERROR\n\nThe AI did not return a result.\n\nBlock reason: ' + reason + '\n\n```json\n' + JSON.stringify(r).slice(0, 800) + '\n```';
}

return [{ json: { script: text } }];
